    ok: f.status === 'evidence_found' || f.status === 'no_evidence',
    summary: f.summary || '',
    findings: f.findings || [],
    evidence: f.evidence || [],
    confidence: typeof f.confidence === 'number' ? Math.max(0, Math.min(1, f.confidence)) : 0,
    window: f.window || null,
